  ('d8d34683-727d-41c4-8d93-6618237ae89d', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', null, 'topic'::public.curated_course_node_type, 'Materials Classes Used in Medicine: Polymers, Metals, Ceramics, and Composites', 'Compare the major materials families used in medicine and match their properties to device functions.', 1),
