  ('ab0e51ed-1f42-4847-bd74-c24f13f493a7', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', null, 'topic'::public.curated_course_node_type, 'Surface Chemistry, Wettability, and Protein Adsorption', 'Explain how surface energy, chemistry, topography, and adsorbed proteins shape early biological response.', 2),
