  ('c6b4452b-b794-47e9-98f1-f858b8853dc3', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', null, 'topic'::public.curated_course_node_type, 'Cell-Material Interactions and Tissue Integration', 'Connect extracellular matrix cues, cell adhesion, cytocompatibility, and tissue integration to biomaterial performance.', 3),
