  ('5d0123a9-270a-42b6-afe6-92edeb914784', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', 'c6b4452b-b794-47e9-98f1-f858b8853dc3', 'subtopic'::public.curated_course_node_type, 'Cytocompatibility and Cell Assays', 'Students need to know how cell-based tests generate early evidence of material safety and function.', 1),
  ('0723d437-8645-44cd-9a3d-fe86366e5f18', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', '5d0123a9-270a-42b6-afe6-92edeb914784', 'concept'::public.curated_course_node_type, 'Cytotoxicity, viability, proliferation, apoptosis, and necrosis', null, 0),
