  ('c970b5c2-52d3-472b-a4e0-83bf48bda48b', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', '5d0123a9-270a-42b6-afe6-92edeb914784', 'concept'::public.curated_course_node_type, 'Direct-contact, extract, and indirect-contact assay formats', null, 2),
