  ('845ad695-7c3a-4607-997c-c8227244da3b', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', '81316328-6ecb-4590-898d-2ff5094a0044', 'concept'::public.curated_course_node_type, 'Osteointegration, endothelialization, epithelialization, and soft-tissue integration', null, 0),
