  ('1f17242c-a5d4-4e22-beff-87fa71cf1c2b', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', 'b65d1817-d200-4830-b666-85bca17f4cb7', 'concept'::public.curated_course_node_type, 'S-N Curve, Fatigue Limit, Crack Initiation, Crack Propagation, and Fracture Surface', null, 0),
