  ('d0f97ba8-bf1a-421f-b9e6-ca9f762ed2ea', '16ab408e-eb5b-4afa-8514-c6f26b5169b5', null, 'topic'::public.curated_course_node_type, 'Sterilization, Manufacturing, Packaging, and Shelf-Life Constraints', 'Understand how processing, sterilization, packaging, and storage alter material properties and device safety.', 9),
